// src/components/Asistencia.jsx
import React, { useState } from "react";
import "./Asistencia.css";

function Asistencia() {
  const [fecha, setFecha] = useState("");
  const [curso, setCurso] = useState("");
  const [asignatura, setAsignatura] = useState("");
  const [modo, setModo] = useState(""); // "consulta" o "registro"
  const [resultado, setResultado] = useState(null);

  const handleBuscar = () => {
    if (!fecha || !curso || !asignatura) {
      alert("Selecciona todos los campos.");
      return;
    }
    setModo("consulta");
    setResultado("cargando");
    // Aquí luego irá la petición GET para consultar asistencias
  };

  const handleRegistrar = () => {
    if (!fecha || !curso || !asignatura) {
      alert("Selecciona todos los campos.");
      return;
    }
    setModo("registro");
    setResultado("cargando");
    // Aquí luego irá la petición GET para obtener estudiantes del curso
  };

  return (
    <div className="asistencia-container">
      <h2>Gestión de Asistencia</h2>

      <div className="filtros-asistencia">
        <input type="date" value={fecha} onChange={(e) => setFecha(e.target.value)} />
        
        <select value={curso} onChange={(e) => setCurso(e.target.value)}>
          <option value="">Seleccione curso</option>
          {/* Aquí luego se cargarán dinámicamente los cursos */}
          <option value="1">Curso 1</option>
          <option value="2">Curso 2</option>
        </select>

        <select value={asignatura} onChange={(e) => setAsignatura(e.target.value)}>
          <option value="">Seleccione asignatura</option>
          {/* Aquí luego se cargarán dinámicamente las asignaturas */}
          <option value="1">Matemáticas</option>
          <option value="2">Historia</option>
        </select>

        <button onClick={handleBuscar}>Buscar</button>
        <button onClick={handleRegistrar}>Registrar asistencia</button>
      </div>

      <div className="resultados-asistencia">
        {resultado === "cargando" && <p>Cargando datos...</p>}

        {modo === "consulta" && resultado !== null && resultado !== "cargando" && (
          <div>
            <h3>Asistencias encontradas:</h3>
            {/* Aquí se mostrarán las asistencias con estado */}
          </div>
        )}

        {modo === "registro" && resultado !== null && resultado !== "cargando" && (
          <div>
            <h3>Registrar asistencia:</h3>
            {/* Aquí se mostrará el formulario para marcar presente/ausente */}
          </div>
        )}
      </div>
    </div>
  );
}

export default Asistencia;
